using FolderVerse;
using Microsoft.Xna.Framework;
using Microsoft.Xna.Framework.Graphics;
using System.Reflection;
using var game=new CurtainCheck(args[0]);game.Run();
sealed class CurtainCheck(string output):Game1{
 const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;SpriteBatch batch=null!;int frame;Color[] expected=null!;
 object Get(string n)=>typeof(Game1).GetField(n,F)!.GetValue(this)!;void Set(string n,object value)=>typeof(Game1).GetField(n,F)!.SetValue(this,value);object Call(string n,params object[] a)=>typeof(Game1).GetMethod(n,F)!.Invoke(this,a)!;
 static void Check(bool ok,string text){if(!ok)throw new Exception(text);Console.WriteLine("PASS "+text);}
 protected override void LoadContent(){Window.Position=new(-3000,-3000);Directory.CreateDirectory(output);AppContext.SetData("APP_CONTEXT_BASE_DIRECTORY",Environment.GetEnvironmentVariable("GAME_RUNTIME"));Content.RootDirectory=Path.Combine(Environment.GetEnvironmentVariable("OLD_RUNTIME")!,"Content");base.LoadContent();Set("_autoSaveEnabled",false);Set("_demoActive",false);Set("_autoPlay",false);Set("_conquestOverviewEnabled",true);var w=(WorldSetup)Get("_setup");w.SetParticipantCounts(2,2);w.SetWorld(2);w.SetCast(123);w.SetPlacement(456);w.SelectPlayer(0);w.HumanPlayers.Add(0);((WorldPreview)Get("_world")).ShowSetup(w,true);((CubeNet)Get("_net")).Home(w);Set("_conquestOverviewTurn",-1);w.Industry.Queue(1);Call("BeginIndustry");Set("_industryAge",100d);Set("_manufacturingActive",false);batch=(SpriteBatch)Get("_spriteBatch");}
 Color[] Capture(int mode){using var target=new RenderTarget2D(GraphicsDevice,1920,1080);GraphicsDevice.SetRenderTarget(target);GraphicsDevice.Clear(new Color(16,35,46));if(mode==0){batch.Begin();Call("DrawIndustry");Call("DrawPhasePlaque");batch.End();}else if(mode<3){Call("DrawConquestOverview",new Rectangle(0,0,1920,1080),Matrix.Identity,GraphicsDevice.Viewport);if(mode==2){batch.Begin();Call("DrawConquestTransition");batch.End();}}else{batch.Begin();Call("DrawConquestTransition");batch.End();}GraphicsDevice.SetRenderTarget(null);var pixels=new Color[1920*1080];target.GetData(pixels);using(var file=File.Create(Path.Combine(output,"curtain-entry-"+mode+"-"+frame+".png")))target.SaveAsPng(file,1920,1080);return pixels;}
 protected override void Update(GameTime t){}
 protected override void Draw(GameTime t){
  if(frame==0){expected=Capture(0);Call("EnterDomesticAfterIndustry");Check((bool)Get("_conquestOverview")&&(int)Get("_conquestStage")==0&&(bool)Get("_conquestEntryFromIndustry"),"industry enters curtain closing with source scene retained");var raw=Capture(1);Check(raw.SequenceEqual(expected),"first transition frame is industry, never conquest broadcast");}
  if(frame==1){Set("_conquestAge",.325d);var closing=Capture(2);Check(Enumerable.Range(0,1080).All(y=>closing[y*1920+960]==expected[y*1920+960]),"uncovered center remains the old industry scene while curtain closes");Check(closing[0]!=expected[0],"curtain is already visible at screen edge");Set("_conquestAge",.65d);Call("UpdateConquestOverview",0d,false);Check((int)Get("_conquestStage")==1&&!(bool)Get("_conquestEntryFromIndustry"),"broadcast replaces industry only after full closure");var closed=Capture(3);Check(closed.All(c=>c!=new Color(16,35,46)),"closed curtain covers the whole frame before scene reveal");}
  if(frame==2){Set("_conquestStage",0);Set("_conquestAge",0d);Set("_conquestEntryFromIndustry",true);Call("UpdateConquestOverview",0d,true);Check((int)Get("_conquestStage")==6&&(bool)Get("_conquestEntryFromIndustry"),"skip during entry closes over industry rather than flashing the skipped broadcast");Check(Capture(1).SequenceEqual(expected),"skip preserves source scene until curtain closes");Console.WriteLine("PASS industry-to-conquest curtain ordering");Exit();}frame++;
 }
}
